<script setup>
import { computed, ref, watch } from 'vue'
import { store, activeWorkData } from '../store.js'
import UiIcon from './UiIcon.vue'
const selectedScope = ref('global')
const chapters = computed(() => (activeWorkData.value.chapters || []).flatMap(v => v.chapters || []))
const selected = computed(() => selectedScope.value === 'global' ? chapters.value : chapters.value.filter(c => c.id === selectedScope.value))
const stats = computed(() => {
  const texts = selected.value.map(c => c.content || '')
  const paragraphs = texts.flatMap(t => t.split(/\r?\n/).map(p => p.trim()).filter(Boolean))
  return { words: texts.reduce((n,t) => n+t.length,0), written:texts.filter(t=>t.trim()).length, paragraphs:paragraphs.length, average:paragraphs.length ? Math.round(paragraphs.reduce((n,p)=>n+p.length,0)/paragraphs.length) : 0, longParagraphs:paragraphs.filter(p=>p.length>300).length }
})
const chart = computed(() => selected.value.slice(-12).map(c => ({id:c.id,title:c.title,words:(c.content || '').length})))
const maxWords = computed(() => Math.max(1,...chart.value.map(c=>c.words)))
const openChapter = id => { store.activeChapterId=id; store.activeMenuItem='写作编辑器' }
watch(() => store.activeWorkId,()=>{selectedScope.value='global'})
</script>
<template>
  <section class="analysis-workspace">
    <header class="analysis-heading"><div><span class="analysis-eyebrow">作品数据</span><h2>看见创作的进度</h2><p>基于作品正文的本地统计，帮助你整理章节与阅读排版。</p></div><select v-model="selectedScope" aria-label="统计章节范围"><option value="global">全书统计</option><option v-for="c in chapters" :key="c.id" :value="c.id">{{c.title}}</option></select></header>
    <div class="analysis-summary"><div><span>正文字符数</span><strong>{{stats.words.toLocaleString()}}<small>字</small></strong></div><div><span>已有正文</span><strong>{{stats.written}}<small>/ {{selected.length}} 章</small></strong></div><div><span>正文段落</span><strong>{{stats.paragraphs.toLocaleString()}}<small>段</small></strong></div><div><span>平均段落长度</span><strong>{{stats.average}}<small>字</small></strong></div></div>
    <div class="analysis-columns"><section class="analysis-panel"><div class="analysis-panel-heading"><h3>章节字数</h3><span>{{ selectedScope === 'global' ? '最近 12 章' : '所选章节' }}</span></div><div v-if="!chart.length" class="analysis-empty"><UiIcon name="book" :size="28" /><p>写下第一个章节后，数据会出现在这里。</p></div><div v-for="c in chart" :key="c.id" class="chapter-bar-row"><button :title="c.title" @click="openChapter(c.id)">{{c.title}}</button><div class="chapter-bar-track"><span :style="{width:(c.words/maxWords*100)+'%'}"></span></div><span>{{c.words.toLocaleString()}}</span></div><p class="analysis-footnote">字数按正文字符统计，包含标点与空白；条形长度仅表示各章节的字数差异。</p></section><aside class="analysis-panel"><span class="analysis-note-icon"><UiIcon name="pen" :size="22" /></span><h3>整理下一步</h3><p v-if="!stats.words">目前还没有正文。先完成一个章节，再回来查看文字与段落统计。</p><template v-else><p v-if="selected.length > stats.written">有 {{selected.length-stats.written}} 个章节还没有正文，可以从大纲开始逐章推进。</p><p v-else>所选范围内的章节都已有正文，可以继续校对或进入漫剧工坊进行拆解。</p><p v-if="stats.longParagraphs">发现 {{stats.longParagraphs}} 个超过 300 字的段落。可以结合阅读节奏，考虑是否拆段。</p></template><div class="analysis-note">这些数据描述文本结构，不代表作品质量、平台排名或读者留存概率。</div><button class="analysis-link" @click="store.activeMenuItem='章节管理'">整理章节<UiIcon name="arrow" :size="15" /></button><button class="analysis-link" @click="store.activeMenuItem='漫剧工坊'">前往漫剧工坊<UiIcon name="arrow" :size="15" /></button></aside></div>
  </section>
</template>
<style scoped>
.analysis-workspace{max-width:1320px;margin:auto}.analysis-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;margin-bottom:25px}.analysis-eyebrow{font-size:11px;color:var(--text-category)}.analysis-heading h2{font-size:25px;font-weight:600;margin:8px 0 9px}.analysis-heading p{font-size:13px;color:var(--text-secondary);margin:0;line-height:1.8}.analysis-heading select{max-width:260px;min-width:0;background:var(--panel-bg);color:var(--text-primary);border:1px solid var(--border-color);padding:10px 12px;border-radius:6px;font-size:12px}.analysis-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:var(--panel-bg);border:1px solid var(--border-color);border-radius:10px;padding:24px 0;margin-bottom:22px}.analysis-summary>div{padding:0 25px;border-right:1px solid var(--border-color);min-width:0}.analysis-summary>div:last-child{border:0}.analysis-summary span{font-size:12px;color:var(--text-secondary)}.analysis-summary strong{display:block;font-size:27px;font-weight:600;margin-top:13px;font-variant-numeric:tabular-nums}.analysis-summary small{font-size:11px;font-weight:400;color:var(--text-category);margin-left:6px}.analysis-columns{display:grid;grid-template-columns:minmax(0,2fr) minmax(230px,1fr);gap:22px}.analysis-panel{background:var(--panel-bg);border:1px solid var(--border-color);border-radius:10px;padding:24px;min-width:0}.analysis-panel-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:24px;gap:12px}.analysis-panel h3{font-size:15px;font-weight:600;margin:0}.analysis-panel-heading>span{font-size:11px;color:var(--text-category)}.chapter-bar-row{display:grid;grid-template-columns:minmax(70px,1fr) minmax(40px,2fr) 42px;align-items:center;gap:13px;font-size:11px;margin:17px 0}.chapter-bar-row button{font:inherit;color:var(--text-secondary);background:none;border:0;padding:0;text-align:left;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.chapter-bar-row button:hover{color:var(--accent-color)}.chapter-bar-row>span{text-align:right;font-variant-numeric:tabular-nums;color:var(--text-secondary)}.chapter-bar-track{height:7px;background:var(--hover-bg);border-radius:3px;overflow:hidden}.chapter-bar-track>span{display:block;height:100%;background:var(--accent-color);opacity:.7;border-radius:3px}.analysis-footnote,.analysis-note{font-size:11px;line-height:1.8;color:var(--text-category);margin:24px 0 0}.analysis-note{background:var(--surface-subtle);padding:13px;border-radius:6px;margin-bottom:18px}.analysis-note-icon{display:inline-flex;color:var(--accent-color);background:var(--accent-bg);padding:12px;border-radius:8px;margin-bottom:18px}.analysis-panel>p:not(.analysis-footnote){font-size:13px;color:var(--text-secondary);line-height:1.9;margin:15px 0}.analysis-link{display:flex;align-items:center;justify-content:space-between;gap:12px;width:100%;border:0;background:none;color:var(--text-secondary);font-size:12px;padding:11px 0}.analysis-link:hover{color:var(--accent-color)}.analysis-empty{text-align:center;color:var(--text-category);font-size:13px;padding:25px}.analysis-empty p{margin:12px 0}@media(max-width:1000px){.analysis-columns{grid-template-columns:1fr}.analysis-summary>div{padding:0 17px}.analysis-summary strong{font-size:23px}}@media(max-width:600px){.analysis-heading{align-items:flex-start;flex-direction:column}.analysis-heading h2{font-size:22px}.analysis-heading select{width:100%;max-width:none}.analysis-summary{grid-template-columns:repeat(2,minmax(0,1fr));row-gap:23px}.analysis-summary>div:nth-child(2){border-right:0}.analysis-panel{padding:18px}.analysis-summary strong{font-size:22px}.chapter-bar-row{gap:8px;grid-template-columns:minmax(55px,1fr) minmax(35px,1fr) 36px}}
</style>